package dev.terminalagent.client;
import java.io.Console; import java.net.URI; import java.net.http.*; import java.nio.charset.StandardCharsets; import java.util.*;
public class Main {
 static String json(String s){ return "\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\""; }
 public static void main(String[] args) throws Exception { Console c=System.console(); if(c==null) { System.err.println("Interactive console required"); return; } String url=System.getenv("AGENT_SERVER_URL"); if(url==null || !url.startsWith("https://")) throw new IllegalArgumentException("Set AGENT_SERVER_URL to an HTTPS URL"); HttpClient http=HttpClient.newHttpClient(); String name=c.readLine("Username: "); char[] password=c.readPassword("Password: "); if(password==null) return; String body="{\"username\":"+json(name)+",\"password\":"+json(new String(password))+"}"; Arrays.fill(password,'\0'); var response=http.send(HttpRequest.newBuilder(URI.create(url+"/api/login")).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8)).build(),HttpResponse.BodyHandlers.ofString()); if(response.statusCode()!=200){System.err.println("Login failed: "+response.statusCode());return;} var m=java.util.regex.Pattern.compile("\"token\"\s*:\s*\"([^\"]+)\"").matcher(response.body()); if(!m.find()) throw new IllegalStateException("Invalid login response"); String token=m.group(1); System.out.println("Logged in. Commands: /status, /logout, /exit"); String line; while((line=c.readLine("> "))!=null){ if(line.equals("/status")){ var res=http.send(HttpRequest.newBuilder(URI.create(url+"/api/me")).header("Authorization","Bearer "+token).GET().build(),HttpResponse.BodyHandlers.ofString()); System.out.println(res.statusCode()==200?res.body():"Session unavailable: "+res.statusCode()); } else if(line.equals("/logout")){ var res=http.send(HttpRequest.newBuilder(URI.create(url+"/api/logout")).header("Authorization","Bearer "+token).POST(HttpRequest.BodyPublishers.noBody()).build(),HttpResponse.BodyHandlers.discarding()); System.out.println(res.statusCode()==200?"Logged out":"Logout failed: "+res.statusCode()); return; } else if(line.equals("/exit")) return; else System.out.println("V0.1 supports /status, /logout, /exit only."); } }
}
